from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
old='<section id="view-time" class="view"><div class="page-head"><div><div class="eyebrow">ARBEITSZEIT</div><h1>Zeiterfassung</h1><p>Geplante und tatsächliche Arbeitszeiten im Blick behalten.</p></div></div><div class="card table-card"><div class="empty">Zeiterfassung ist für die nächste Ausbaustufe vorbereitet.</div></div></section>'
new='''<section id="view-time" class="view"><div class="page-head"><div><div class="eyebrow">ARBEITSZEIT</div><h1>Zeiterfassung</h1><p>Geplante und tatsächliche Arbeitszeiten vergleichen, Abweichungen prüfen und Zeiten bestätigen.</p></div><select id="timePeriod" onchange="renderTimeTracking()"><option value="week">Diese Woche</option><option value="month">Dieser Monat</option></select></div><div class="stats" id="timeStats"></div><div class="card table-card" style="margin-top:14px"><div class="table-head"><h3>Zeiteinträge</h3><input id="timeSearch" placeholder="Mitarbeiter oder Schicht suchen ..." oninput="renderTimeTracking()"></div><div style="overflow:auto"><table style="width:100%;border-collapse:collapse;min-width:1050px"><thead><tr style="color:var(--muted);font-size:11px;text-align:left"><th style="padding:10px">Mitarbeiter</th><th>Datum</th><th>Schicht</th><th>Geplant</th><th>Tatsächlich</th><th>Pause</th><th>IST</th><th>Differenz</th><th>Status</th><th></th></tr></thead><tbody id="timeTableBody"></tbody></table></div></div><div class="card table-card" style="margin-top:14px"><div class="table-head"><h3>Abweichungen</h3><span class="badge" id="timeDeviationCount">0</span></div><div id="timeDeviations"></div></div></section>'''
if old not in s: raise SystemExit('time section not found')
s=s.replace(old,new,1)
anchor='function renderSettings(){'
fn=r'''let timeEntries=store.get('timeEntries',{});
function timeTrackingDates(){const mode=document.getElementById('timePeriod')?.value||'week';if(mode==='week')return currentWeekDates().map(iso);const b=currentWeekDates()[0],y=b.getFullYear(),m=b.getMonth(),last=new Date(y,m+1,0).getDate();return Array.from({length:last},(_,i)=>iso(new Date(y,m,i+1)))}
function timeMinutes(s,e){if(!s||!e)return 0;const a=s.split(':').map(Number),b=e.split(':').map(Number);let x=b[0]*60+b[1]-(a[0]*60+a[1]);if(x<0)x+=1440;return x}
function getTimeEntry(a){return timeEntries[a.id]||{actualStart:'',actualEnd:'',breakMin:0,status:'open'}}
function renderTimeTracking(){const dates=timeTrackingDates(),q=(document.getElementById('timeSearch')?.value||'').toLowerCase(),rows=assignments.filter(a=>dates.includes(a.date)).filter(a=>{const e=employees.find(x=>x.id===a.employeeId);return `${e?.first||''} ${e?.last||''} ${a.type}`.toLowerCase().includes(q)}).sort((a,b)=>a.date.localeCompare(b.date));let planned=0,actual=0,open=0,dev=[];rows.forEach(a=>{const t=typeById(a.type),te=getTimeEntry(a),pm=timeMinutes(a.start||t?.start,a.end||t?.end);planned+=pm;if(te.actualStart&&te.actualEnd){const am=Math.max(0,timeMinutes(te.actualStart,te.actualEnd)-Number(te.breakMin||0));actual+=am;const diff=am-pm;if(Math.abs(diff)>=15)dev.push({a,diff,te})}else open++});document.getElementById('timeStats').innerHTML=`<div class="stat"><div><small>Geplante Stunden</small><strong>${(planned/60).toFixed(1)}</strong><em>im Zeitraum</em></div></div><div class="stat"><div><small>Erfasste Stunden</small><strong>${(actual/60).toFixed(1)}</strong><em>tatsächliche Zeit</em></div></div><div class="stat"><div><small>Abweichung</small><strong>${((actual-planned)/60).toFixed(1)}</strong><em>Stunden gesamt</em></div></div><div class="stat"><div><small>Offene Zeiteinträge</small><strong>${open}</strong><em>noch nicht erfasst</em></div></div>`;document.getElementById('timeTableBody').innerHTML=rows.length?rows.map(a=>{const e=employees.find(x=>x.id===a.employeeId),t=typeById(a.type),te=getTimeEntry(a),ps=a.start||t?.start||'',pe=a.end||t?.end||'',pm=timeMinutes(ps,pe),am=te.actualStart&&te.actualEnd?Math.max(0,timeMinutes(te.actualStart,te.actualEnd)-Number(te.breakMin||0)):0,diff=te.actualStart&&te.actualEnd?am-pm:null,status=te.status==='confirmed'?'Bestätigt':te.actualStart&&te.actualEnd?'Erfasst':'Offen';return `<tr style="border-top:1px solid var(--line)"><td style="padding:12px 10px"><b>${e?e.first+' '+e.last:'Mitarbeiter'}</b></td><td>${new Date(a.date+'T00:00:00').toLocaleDateString('de-DE')}</td><td><b>${a.type}</b></td><td>${ps}–${pe}</td><td>${te.actualStart&&te.actualEnd?te.actualStart+'–'+te.actualEnd:'–'}</td><td>${Number(te.breakMin||0)} Min.</td><td>${te.actualStart&&te.actualEnd?(am/60).toFixed(2)+' Std.':'–'}</td><td style="color:${diff===null?'var(--muted)':Math.abs(diff)<15?'var(--green)':diff>0?'var(--amber)':'var(--red)'}">${diff===null?'–':(diff>=0?'+':'')+(diff/60).toFixed(2)+' Std.'}</td><td><span class="status ${te.status==='confirmed'?'active':'inactive'}">${status}</span></td><td><button class="ghost" onclick="editTimeEntry('${a.id}')">Bearbeiten</button></td></tr>`}).join(''):'<tr><td colspan="10"><div class="empty">Keine geplanten Schichten im gewählten Zeitraum.</div></td></tr>';document.getElementById('timeDeviationCount').textContent=dev.length;document.getElementById('timeDeviations').innerHTML=dev.length?dev.map(x=>{const e=employees.find(y=>y.id===x.a.employeeId);return `<div class="section-box" style="margin-bottom:8px;display:flex;justify-content:space-between"><div><b>${e?e.first+' '+e.last:'Mitarbeiter'} · ${x.a.type}</b><small style="display:block;color:var(--muted)">${new Date(x.a.date+'T00:00:00').toLocaleDateString('de-DE')}</small></div><span style="color:${x.diff>0?'var(--amber)':'var(--red)'}">${x.diff>0?'+':''}${(x.diff/60).toFixed(2)} Std.</span></div>`}).join(''):'<div class="notice">✓ Keine relevanten Zeitabweichungen im Zeitraum.</div>'}
function editTimeEntry(id){const a=assignments.find(x=>x.id===id);if(!a)return;const t=typeById(a.type),e=employees.find(x=>x.id===a.employeeId),old=getTimeEntry(a),start=prompt(`${e?e.first+' '+e.last:'Mitarbeiter'} · ${a.type}\nTatsächlicher Beginn:`,old.actualStart||a.start||t?.start||'');if(start===null)return;const end=prompt('Tatsächliches Ende:',old.actualEnd||a.end||t?.end||'');if(end===null)return;const br=prompt('Pause in Minuten:',String(old.breakMin||0));if(br===null)return;const confirmEntry=confirm('Zeiteintrag direkt als bestätigt markieren?');timeEntries[id]={actualStart:start,actualEnd:end,breakMin:Math.max(0,Number(br)||0),status:confirmEntry?'confirmed':'recorded'};store.set('timeEntries',timeEntries);renderTimeTracking();showSaveToast('Zeiteintrag gespeichert',`${e?e.first+' '+e.last:'Mitarbeiter'} · ${a.type} wurde aktualisiert.`)}
'''
if anchor not in s: raise SystemExit('settings anchor not found')
s=s.replace(anchor,fn+anchor,1)
# ensure navigation renders time tracking
needle="if(name==='absence')renderAbsences();"
if needle in s and "if(name==='time')renderTimeTracking();" not in s:s=s.replace(needle,"if(name==='time')renderTimeTracking();"+needle,1)
# initial render if available
needle2='renderLibrary();renderPlanEmployeePool();renderCalendar();renderEmployees();'
if needle2 in s and 'renderTimeTracking();' not in s[s.find(needle2):s.find(needle2)+300]:s=s.replace(needle2,needle2+'renderTimeTracking();',1)
p.write_text(s,encoding='utf-8');print('Zeiterfassung Basis eingebaut')